import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"8250 uart","description":"","frontmatter":{},"headers":[],"relativePath":"notes/hardware/serial/8250uart.md","filePath":"notes/hardware/serial/8250uart.md"}'),s={name:"notes/hardware/serial/8250uart.md"};function i(n,e,l,c,h,d){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="_8250-uart" tabindex="-1">8250 uart <a class="header-anchor" href="#_8250-uart" aria-label="Permalink to &quot;8250 uart&quot;">​</a></h1><p><a href="https://www.analog.com/cn/resources/analog-dialogue/articles/uart-a-hardware-communication-protocol.html" target="_blank" rel="noreferrer">uart通信协议</a></p><blockquote><p>The UART performs serial-te-parallel conversion on data characters received from a peripheral device or a MODEM, and parallel-to-serial conversion on data characters re ceived from the CPU. The CPU can read the complete status of the UART at any time during the functional opera tion.</p></blockquote><p>8250 UART 最初指 National Semiconductor 的 8250 系列通用异步收发器，负责在 CPU 的并行字节访问与串行线路的逐位传输之间进行转换；后来形成了以 8250、16450、16550A 为代表的寄存器兼容体系，其中 16550 在 8250/16450 的基础上增加了收发 FIFO。Linux 中的“8250 UART”通常不是单指原始 8250 芯片，而是泛指采用这套寄存器模型的 UART 控制器，包括物理芯片、SoC 内置 UART、PCI 串口以及虚拟机模拟串口。Linux 的 drivers/tty/serial/8250/ 就是面向这类兼容设备的通用驱动框架<br> docs:</p><ol><li><a href="https://www.scribd.com/document/849237217/uart-8250a#google_vignette" target="_blank" rel="noreferrer">https://www.scribd.com/document/849237217/uart-8250a#google_vignette</a></li><li><a href="https://media.digikey.com/pdf/Data%20Sheets/Texas%20Instruments%20PDFs/PC16550D.pdf" target="_blank" rel="noreferrer">https://media.digikey.com/pdf/Data Sheets/Texas Instruments PDFs/PC16550D.pdf</a></li><li><a href="https://uart16550.readthedocs.io/_/downloads/en/latest/pdf/" target="_blank" rel="noreferrer">https://uart16550.readthedocs.io/_/downloads/en/latest/pdf/</a></li><li><a href="https://web.archive.org/web/20160503070506/http://archive.pcjs.org/pubs/pc/datasheets/8250A-UART.pdf" target="_blank" rel="noreferrer">https://web.archive.org/web/20160503070506/http://archive.pcjs.org/pubs/pc/datasheets/8250A-UART.pdf</a></li><li><a href="https://www.scs.stanford.edu/10wi-cs140/pintos/specs/pc16550d.pdf" target="_blank" rel="noreferrer">https://www.scs.stanford.edu/10wi-cs140/pintos/specs/pc16550d.pdf</a></li></ol><h2 id="registers" tabindex="-1">registers <a class="header-anchor" href="#registers" aria-label="Permalink to &quot;registers&quot;">​</a></h2><p>ref: uart16550</p><p><img src="https://raw.githubusercontent.com/sandyyyz/Image-hosting/main/img/20260917135631916.png" alt="uart_16550_registers"></p><p>uart 8250:<br><img src="https://raw.githubusercontent.com/sandyyyz/Image-hosting/main/img/20260917153951886.png" alt="uart_8250_registers"></p><h3 id="line-control-register-lcr" tabindex="-1">Line Control Register (LCR) <a class="header-anchor" href="#line-control-register-lcr" aria-label="Permalink to &quot;Line Control Register (LCR)&quot;">​</a></h3><blockquote><p>The line control register allows the specification of the format of the asynchronous data communication used. A bit in the register also allows access to the Divisor Latches, which define the baud rate. Reading from the register is allowed to check the current settings of the communication.</p></blockquote><h3 id="interrupt-enable-register-ier" tabindex="-1">Interrupt Enable Register (IER) <a class="header-anchor" href="#interrupt-enable-register-ier" aria-label="Permalink to &quot;Interrupt Enable Register (IER)&quot;">​</a></h3><blockquote><p>This register allows enabling and disabling interrupt generation by the UART.</p></blockquote><h3 id="fifo-control-register-fcr" tabindex="-1">FIFO Control Register (FCR) <a class="header-anchor" href="#fifo-control-register-fcr" aria-label="Permalink to &quot;FIFO Control Register (FCR)&quot;">​</a></h3><blockquote><p>The FCR allows selection of the FIFO trigger level (the number of bytes in FIFO required to enable the Received Data Available interrupt). In addition, the FIFOs can be cleared using this register.</p></blockquote><h3 id="modem-control-register-mcr" tabindex="-1">Modem Control Register(MCR) <a class="header-anchor" href="#modem-control-register-mcr" aria-label="Permalink to &quot;Modem Control Register(MCR)&quot;">​</a></h3><blockquote><p>The modem control register allows transferring control signals to a modem connected to the UART.</p></blockquote><h3 id="divisor-latches" tabindex="-1">Divisor Latches <a class="header-anchor" href="#divisor-latches" aria-label="Permalink to &quot;Divisor Latches&quot;">​</a></h3><blockquote><p>The divisor latches can be accessed by setting the 7th bit of LCR to ‘1’. You should restore this bit to ‘0’ after setting the divisor latches in order to restore access to the other registers that occupy the same addresses.<br> The 2 bytes form one 16-bit register,<br> The value set should be equal to (system clock speed) / (16 x desired baud rate).</p></blockquote><h3 id="line-status-register" tabindex="-1">Line Status Register <a class="header-anchor" href="#line-status-register" aria-label="Permalink to &quot;Line Status Register&quot;">​</a></h3><p>This 8-bit register provides status information to the CPU concerning the data transfer.<br> Bit 5 indicates that the UART is ready to accept a new character for transmission.</p>',21)])])}const g=t(s,[["render",i]]);export{p as __pageData,g as default};
